      "name": "functional_needs",
      "category": "functionality",
      "value": "Receive trading instructions from the client-facing service; validate completeness and authorization; classify instructions as buy, sell, amend, or cancel; apply trading rules to determine match compatibility; execute matches and record results; keep orders open or reject them when appropriate; publish executed trade details, partial fill information, rejection status, or cancellation status; maintain internal records for later inspection."
    },
    {
      "name": "business_rules",
      "category": "business_logic",
      "value": "Trading instructions must be complete and authorized before processing; orders must be classified into valid instruction types; matching must follow applicable trading rules; compatible orders may be matched, otherwise the order is left open or rejected based on the instruction and rule outcome; partial fills and cancellations must be represented in the outcome."
    },
    {
      "name": "data_entities",
      "category": "data",
      "value": "Trading instructions, order types, stock orders, matched trades, executed trade details, partial fill information, rejection status, cancellation status, internal trading records."
    },
    {
      "name": "constraints",
      "category": "constraints",
      "value": "Only authorized instructions may be processed; the system operates as a subsystem within a larger trading platform and must publish outcomes to other components; authorized managers must be able to inspect stored information."
    },
    {
      "name": "quality_concerns",
      "category": "quality",
      "value": "Accuracy of validation, classification, matching, and status reporting; traceability through retained records; reliable publication of trading outcomes for downstream components."
    },
    {
      "name": "boundary_conditions",
      "category": "exceptions",
      "value": "If an instruction is incomplete or unauthorized, it should not be processed normally; if no compatible match is found, the order should remain open or be rejected depending on the instruction and rule outcome; outcomes may be executed trade, partial fill, rejection, or cancellation."
    }
  ]
